return $input.all().map((item) => {
  const row = item.json;
  const greeting = row.patient_first_name ? `Hola ${row.patient_first_name}, ¿cómo estás?` : 'Hola, ¿cómo estás?';
  const bodyText = row.reminder_type === '24h'
    ? `${greeting} Te recordamos tu turno programado dentro de las próximas 24 horas. Confirmá tu asistencia o avisanos si necesitás reprogramar. Si preferís no recibir avisos, respondé "baja".`
    : `${greeting} En aproximadamente dos horas tenés tu turno programado. Si surge algún imprevisto, avisanos para reorganizar la agenda. Si preferís no recibir avisos, respondé "baja".`;
  return {
    json: {
      ...row,
      wabaPayload: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: row.patient_phone_e164,
        type: 'interactive',
        interactive: {
          type: 'button',
          body: { text: bodyText },
          action: {
            buttons: [
              { type: 'reply', reply: { id: `confirmar_${row.reminder_type}_${row.id}`, title: 'Confirmar turno' } },
              { type: 'reply', reply: { id: `reprogramar_${row.reminder_type}_${row.id}`, title: 'Reprogramar' } }
            ]
          }
        }
      }
    }
  };
});

function constantTimeHexEqual(hexA, hexB) {
  if (!/^[0-9a-f]{64}$/i.test(hexA) || !/^[0-9a-f]{64}$/i.test(hexB)) return false;
  const a = hexA.toLowerCase();
  const b = hexB.toLowerCase();
  try {
    const { timingSafeEqual } = require('node:crypto');
    return timingSafeEqual(Buffer.from(a, 'hex'), Buffer.from(b, 'hex'));
  } catch {
    let diff = 0;
    for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
    return diff === 0;
  }
}
const item = $input.first().json;
const headers = item.headers || {};
const rawKey = String(headers['x-autonomous-key'] || headers['X-Autonomous-Key'] || '').trim();
if (!rawKey || !constantTimeHexEqual(String(item.providedKeySha256 || ''), String(item.expectedKeySha256 || ''))) {
  throw new Error('Acceso no autorizado al webhook de respuestas de turnos');
}
const { expectedKeySha256, providedKeySha256, ...safePayload } = item;
return [{ json: safePayload }];

return $input.all().map((item) => {
  const row = item.json || {};
  const status = String(row.appointment_status || '');
  let eventType = 'heartbeat';
  if (status === 'confirmado') eventType = 'appointment_confirmed';
  else if (status === 'reprogramado') eventType = 'appointment_rescheduled';
  else if (status === 'cancelado') eventType = 'appointment_cancelled';
  else if (row.offered_slot_id) eventType = 'waitlist_filled';
  return {
    json: {
      client_slug: String(row.client_slug || 'clinica-principal'),
      event_type: eventType,
      has_waitlist_offer: Boolean(row.waitlist_id || row.offered_slot_id)
    }
  };
});
